insert into public.products (id, slug, name, brand, category, region, region_warning, description, redemption_steps, terms, image_url, accent_color, gradient, active, is_popular) values
  ('10000000-0000-4000-8000-000000000001', 'playstation-store-usd', 'PlayStation Store Gift Card (USA)', 'PlayStation', 'gaming', 'USA', 'Solo funciona en cuentas PSN registradas en Estados Unidos (USA). No canjeable en cuentas de Latinoamérica ni Europa.', 'Agrega saldo a tu cuenta de PlayStation Network para comprar juegos digitales de PS4 y PS5, DLCs y suscripciones de PS Plus al instante.', '["Inicia sesión en PlayStation Store desde tu consola PS4/PS5 o en store.playstation.com.","Selecciona el ícono de tu perfil y elige ''Canjear código''.","Ingresa el código de 12 caracteres y confirma para acreditar el saldo."]'::jsonb, 'Válido únicamente para cuentas PSN de Estados Unidos. Sin fecha de expiración.', '/cards/playstation.jpg', '#0070d1', 'from-blue-600 to-indigo-900', true, true),
  ('10000000-0000-4000-8000-000000000002', 'nintendo-eshop-usd', 'Nintendo eShop Gift Card (USA)', 'Nintendo', 'gaming', 'USA', 'Compatible únicamente con cuentas Nintendo registradas en Estados Unidos (USA).', 'Compra tus juegos favoritos para Nintendo Switch y Switch 2, pases de expansión y suscripciones Switch Online directamente en la eShop.', '["Abre Nintendo eShop en tu consola desde el menú HOME.","Selecciona la cuenta correspondiente y haz clic en ''Canjear código''.","Introduce el código de 16 caracteres y confirma."]'::jsonb, 'Válido solo en Nintendo eShop región EE. UU. Requiere conexión a internet.', '/cards/nintendo.jpg', '#e60012', 'from-red-600 to-rose-900', true, true),
  ('10000000-0000-4000-8000-000000000003', 'xbox-gift-card-usd', 'Xbox Gift Card (USA)', 'Xbox', 'gaming', 'USA', 'Solo para cuentas Microsoft / Xbox con región en Estados Unidos (USA).', 'Tarjeta de saldo oficial para Xbox Series X|S, Xbox One y Microsoft Store en Windows. Úsala en juegos completos, complementos o Game Pass.', '["Ve a redeem.microsoft.com o abre la Microsoft Store en tu consola Xbox.","Inicia sesión con tu cuenta Microsoft (región USA).","Escribe el código de 25 dígitos y pulsa Siguiente para acreditar el saldo."]'::jsonb, 'Canjeable únicamente en cuentas Microsoft configuradas en Estados Unidos.', '/cards/xbox.jpg', '#107c10', 'from-emerald-600 to-green-950', true, true),
  ('10000000-0000-4000-8000-000000000004', 'steam-wallet-usd', 'Steam Wallet Gift Card (USA / USD)', 'Steam', 'gaming', 'USA', 'Tu cuenta de Steam debe usar moneda USD (Estados Unidos) o compatible sin bloqueo cambiario.', 'Recarga tu cartera de Steam de forma segura para comprar juegos de PC, Steam Deck, DLCs y artículos del mercado de la comunidad.', '["Abre Steam en tu PC e inicia sesión.","Haz clic en tu nombre de usuario (arriba a la derecha) -> Ver mi cartera.","Elige ''Canjear un código de cartera de Steam'' e ingresa el código."]'::jsonb, 'Válido para cuentas con cartera configurada en USD.', '/cards/steam.jpg', '#1b2838', 'from-slate-700 to-slate-950', true, true),
  ('10000000-0000-4000-8000-000000000005', 'roblox-robux-global', 'Roblox Gift Card (Global)', 'Roblox', 'gaming', 'Global', 'El crédito se convierte automáticamente según el país de la cuenta Roblox al momento de canjear.', 'Ideal para regalar Robux o suscripciones Roblox Premium sin vincular tarjetas bancarias a la cuenta de tus hijos.', '["Ingresa a roblox.com/redeem desde cualquier navegador.","Inicia sesión en la cuenta donde deseas recibir el saldo.","Introduce el PIN recibido y selecciona Canjear."]'::jsonb, 'Canjeable a nivel global en Roblox.com.', '/cards/roblox.jpg', '#111827', 'from-zinc-700 to-zinc-950', true, true),
  ('10000000-0000-4000-8000-000000000006', 'freefire-diamantes-latam', 'Free Fire PIN Diamantes (Latam)', 'Garena Free Fire', 'gaming', 'Latam', 'Válido exclusivamente para servidores de Free Fire Latinoamérica mediante PagoStore.', 'Recarga diamantes directo a tu ID de jugador en Garena Free Fire sin pedir contraseñas, usando tu PIN oficial.', '["Entra en pagostore.com y selecciona Free Fire.","Ingresa tu ID de jugador o inicia sesión con tu cuenta.","Elige ''Garena Voucher / PIN'', pega el código y confirma la entrega."]'::jsonb, 'Válido solo para región Latinoamérica.', '/cards/freefire.jpg', '#f59e0b', 'from-amber-600 to-orange-950', true, true),
  ('10000000-0000-4000-8000-000000000007', 'apple-gift-card-usa', 'Apple Gift Card (USA)', 'Apple', 'shopping', 'USA', 'Requiere un Apple ID configurado con región Estados Unidos (USA). No funciona en cuentas de otros países.', 'Saldo oficial para App Store, iCloud+, Apple Music, juegos en iPhone/iPad y servicios digitales de Apple.', '["Abre la App Store en tu iPhone, iPad o Mac.","Pulsa en tu foto de perfil y selecciona ''Canjear tarjeta regalo o código''.","Introduce el código de 16 caracteres manualmente."]'::jsonb, 'Válido exclusivamente en Apple ID de Estados Unidos.', '/cards/apple.jpg', '#1d1d1f', 'from-neutral-700 to-neutral-950', true, false),
  ('10000000-0000-4000-8000-000000000008', 'netflix-gift-card-usa', 'Netflix Gift Card (USA / USD)', 'Netflix', 'streaming', 'USA', 'Solo canjeable en cuentas Netflix facturadas en USD (Estados Unidos).', 'Paga tu suscripción mensual de Netflix sin usar tarjetas de crédito tradicionales ni renovaciones sorpresa.', '["Ingresa a netflix.com/redeem en tu navegador.","Introduce el PIN de regalo que aparece en tu bóveda StoryCheap.","Inicia sesión o crea tu cuenta Netflix para aplicar el saldo."]'::jsonb, 'Válido únicamente para cuentas cuya moneda de facturación sea USD (USA).', '/cards/netflix.jpg', '#e50914', 'from-red-700 to-black', true, false),
  ('10000000-0000-4000-8000-000000000009', 'spotify-premium-usa', 'Spotify Premium Gift Card (USA)', 'Spotify', 'streaming', 'USA', 'Tu cuenta de Spotify debe tener configurado el país Estados Unidos para canjear esta tarjeta.', 'Disfruta de música y podcasts sin anuncios, descarga canciones offline y reproduce bajo demanda.', '["Visita spotify.com/redeem e inicia sesión en tu cuenta.","Escribe el PIN exactamente como aparece en tu orden.","Haz clic en Canjear para extender tu suscripción Premium."]'::jsonb, 'No acumulable con planes familiares o estudiantiles según políticas de Spotify.', '/cards/spotify.jpg', '#1db954', 'from-green-600 to-emerald-950', true, false),
  ('10000000-0000-4000-8000-000000000010', 'razer-gold-pin-global', 'Razer Gold PIN (Global USD)', 'Razer Gold', 'gaming', 'Global', 'Asegúrate de usar la billetera Razer Gold configurada en USD Global.', 'Crédito unificado para miles de juegos y contenidos digitales compatibles con Razer Gold alrededor del mundo.', '["Inicia sesión en gold.razer.com con tu Razer ID.","Selecciona ''Reload Now'' y elige ''Razer Gold PIN''.","Ingresa el número de serie y PIN para acreditar tus fondos."]'::jsonb, 'PIN digital global USD. No reembolsable una vez revelado.', '/cards/razer.jpg', '#44d62c', 'from-lime-600 to-zinc-950', true, false),
  ('10000000-0000-4000-8000-000000000011', 'binance-usdt-gift-card', 'Binance Gift Card USDT (Global)', 'Binance', 'crypto', 'Global', 'Canjeable en cuentas verificadas de Binance que soporten tarjetas de regalo cripto según jurisdicción.', 'Tarjeta de regalo oficial acreditable directamente en USDT en la billetera de fondos de Binance.', '["Abre la app de Binance y ve a Perfil -> Tarjeta de Regalo.","Selecciona ''Canjear'' e introduce el código alfanumérico recibido.","Los USDT se acreditan en tu billetera de fondos al instante."]'::jsonb, 'Requiere cuenta Binance activa.', '/cards/binance.jpg', '#f0b90b', 'from-yellow-500 to-amber-950', true, false)
